    seen = set()
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != bg or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            comp = []
            edge = False
            while q:
                r, c = q.popleft()
                comp.append((r, c))
                if r == 0 or c == 0 or r == h-1 or c == w-1:
                    edge = True
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
